# Efficiency sensitivity
sens=[['Assumed reducer efficiency','Required motor torque (N m)','Required motor shaft mechanical power (W)','Approx current = torque/Kt (A)','Output capacity = min(Tnom,KtIcont) x ratio x eta (N m)','Capacity/target','Margin versus target','Screen interpretation']]
for eta in [.75,.70,.65,.60,.55,.50,.45,.40,.35,.32,.30]:
 tm=T_target/(ratio*eta); pm=P_out/eta; current=tm/Kt; capacity=min(T_cont,Kt*I_cont)*ratio*eta; r=capacity/T_target; margin=(r-1)*100
 if eta>=.40: note='Below simplified continuous torque/current cap and below 180 W label; dynamics/thermal still open'
 elif eta>=.32: note='Small/sensitive reserve in simplified screen; do not freeze design at this efficiency'
 else: note='Fails simplified continuous torque/current cap; input power also exceeds 180 W class label'
 sens.append([eta,tm,pm,current,capacity,r,margin,note])
